<?php require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/../app/layout.php'; require_permission('manage_purchases');
$q=trim($_GET['q']??'');$args=[];$sql="SELECT pu.*,s.party_code,s.party_name,COUNT(pi.id) item_lines FROM purchases pu JOIN suppliers s ON s.id=pu.supplier_id LEFT JOIN purchase_items pi ON pi.purchase_id=pu.id WHERE 1";if($q!==''){$sql.=' AND (pu.purchase_no LIKE ? OR pu.invoice_no LIKE ? OR s.party_name LIKE ? OR s.party_code LIKE ?)';$like='%'.$q.'%';$args=[$like,$like,$like,$like];}$sql.=' GROUP BY pu.id ORDER BY pu.id DESC LIMIT 500';$st=db()->prepare($sql);$st->execute($args);$rows=$st->fetchAll();page_header('Purchase History'); ?>
<form method="get" class="actions no-print"><input name="q" value="<?=e($q)?>" placeholder="Purchase no / supplier invoice / party"><button class="btn">Search</button><a class="btn" href="purchase_new.php">+ New Purchase</a></form><br>
<table><tr><th>Purchase No</th><th>Supplier</th><th>Supplier Invoice</th><th>Date</th><th>Lines</th><th>Total Cost</th><th>Labels</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['purchase_no'])?></td><td><?=e($r['party_code'].' · '.$r['party_name'])?></td><td><?=e($r['invoice_no'])?></td><td><?=e($r['invoice_date'])?></td><td><?=e($r['item_lines'])?></td><td>₹<?=e(number_format($r['total_cost'],2))?></td><td><?php $st2=db()->prepare('SELECT b.id,p.sku FROM batches b JOIN products p ON p.id=b.product_id WHERE b.purchase_id=? ORDER BY b.id');$st2->execute([$r['id']]);foreach($st2->fetchAll() as $b):?><a href="barcode_labels.php?batch_id=<?=$b['id']?>"><?=e($b['sku'])?></a>&nbsp; <?php endforeach;?></td></tr><?php endforeach;?></table><?php page_footer();
